package pricing

import "testing"

func TestCartTotal(t *testing.T) {
	tests := []struct {
		name string
		cart Cart
		want int
	}{
		{
			name: "empty cart",
			cart: Cart{Discount: &Discount{Percent: 10}},
			want: 0,
		},
		{
			name: "single item no discount",
			cart: Cart{
				Items:    []*Item{{Name: "pen", Cents: 150, Qty: 2}},
				Discount: &Discount{Percent: 0},
			},
			want: 300,
		},
		{
			name: "multiple items with discount",
			cart: Cart{
				Items: []*Item{
					{Name: "pen", Cents: 150, Qty: 2},
					{Name: "book", Cents: 1200, Qty: 1},
				},
				Discount: &Discount{Percent: 25},
			},
			want: 1125,
		},
		{
			name: "discount truncates fractional cents",
			cart: Cart{
				Items:    []*Item{{Name: "mug", Cents: 999, Qty: 1}},
				Discount: &Discount{Percent: 10},
			},
			want: 900,
		},
		{
			name: "zero quantity contributes nothing",
			cart: Cart{
				Items:    []*Item{{Name: "pen", Cents: 150, Qty: 0}},
				Discount: &Discount{Percent: 0},
			},
			want: 0,
		},
		{
			name: "full discount",
			cart: Cart{
				Items:    []*Item{{Name: "pen", Cents: 150, Qty: 3}},
				Discount: &Discount{Percent: 100},
			},
			want: 0,
		},
		{
			name: "nil discount means no discount",
			cart: Cart{
				Items: []*Item{{Name: "pen", Cents: 150, Qty: 2}},
			},
			want: 300,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := tt.cart.Total(); got != tt.want {
				t.Errorf("Total() = %d, want %d", got, tt.want)
			}
		})
	}
}

func TestApplyDiscount(t *testing.T) {
	tests := []struct {
		name    string
		cents   int
		percent int
		want    int
	}{
		{name: "no discount", cents: 1000, percent: 0, want: 1000},
		{name: "half off", cents: 1000, percent: 50, want: 500},
		{name: "full discount", cents: 1000, percent: 100, want: 0},
		{name: "percent above 100 clamps to zero", cents: 1000, percent: 150, want: 0},
		{name: "truncates fractional cents", cents: 999, percent: 10, want: 900},
		{name: "zero cents", cents: 0, percent: 30, want: 0},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := ApplyDiscount(tt.cents, tt.percent); got != tt.want {
				t.Errorf("ApplyDiscount(%d, %d) = %d, want %d", tt.cents, tt.percent, got, tt.want)
			}
		})
	}
}

